#include "../color.hpp"
#include <iostream>
using namespace ColorSpace;

int main(int argc, char* argv[]) {
    float h1 = 30.0f, s1 = 0.6f, l1 = 0.5f;
    float h2 = 210.0f, s2 = 0.4f, l2 = 0.7f;

    if (argc > 5) {
        h1 = std::stof(argv[1]);
        s1 = std::stof(argv[2]);
        l1 = std::stof(argv[3]);
        h2 = std::stof(argv[4]);
        s2 = std::stof(argv[5]);
    }
    if (argc > 6) {
        l2 = std::stof(argv[6]);
    }

    HSL hsl1(h1, s1, l1);
    HSL hsl2(h2, s2, l2);

    float hueDiff = ColorConverter::hueDifference(hsl1, hsl2);

    std::cout << hueDiff << std::endl;
    return 0;
}


